      onError: (err, req, res) => res.status(500).end(`Handling ${err} from child on ${req.path} page.`)
    })

    subApp.get('/route', (_req, _res, next) => next('you'))

    app.use('/subapp', subApp).listen()

    const server = app.listen()
    const fetch = makeFetch(server)

    await fetch('/subapp/route').expect(500, 'Handling you from child on /subapp/route page.')
  })
  it('subapps mount on path regardless if path has leading slash', async () => {
    const app = new App()
    const subApp = new App()
    subApp.get('/foo', (_req, res) => {
      res.send('foo')
    })
    app.use('/bar1', subApp)
    app.use('bar2', subApp)
    const fetch = makeFetch(app.listen())
    await fetch('/bar1/foo').expect(200, 'foo')
    await fetch('/bar2/foo').expect(200, 'foo')
  })
  it('should handle HEAD requests to sub-app routes', async () => {
    const app = new App()
    const subApp = new App()

    subApp.get('/resource', (_req, res) => {
      res.send('This is the resource')
    })

    app.use('/api', subApp)

    const server = app.listen()
    const fetch = makeFetch(server)

    // HEAD request should work and return empty body
    const response = await fetch('/api/resource', { method: 'HEAD' })
    expect(response.status).toBe(200)
    const body = await response.text()
    expect(body).toBe('')
  })
  it('should not continue middleware chain if response is already ended', async () => {
    const app = new App()
    const subApp = new App()

    let fallbackCalled = false

    subApp.use((_req, res, next) => {
      res.end('done')
      // Call next after response is ended
      next()
    })

    app.use('/sub', subApp)

    app.use((_req, res) => {
      fallbackCalled = true
      res.send('fallback')
    })

    const server = app.listen()
    const fetch = makeFetch(server)

    await fetch('/sub/test').expect(200, 'done')
    expect(fallbackCalled).toBe(false)
  })
  it('should handle empty sub-app with no middleware', async () => {
    const app = new App()
    const emptySubApp = new App()

    // Mount empty sub-app (no routes or middleware added)
    app.use('/empty', emptySubApp)

    // Add a fallback route on parent
    app.get('/other', (_req, res) => res.send('other'))

    const server = app.listen()
    const fetch = makeFetch(server)

    // Empty sub-app should result in 404 for unmatched paths
    await fetch('/empty/anything').expect(404)
    // Other routes should still work
    await fetch('/other').expect(200, 'other')
  })
  it('should call parent next when sub-app exhausts middleware', async () => {
    const app = new App()
    const subApp = new App()

    // Sub-app has middleware that calls next
    subApp.use((_req, _res, next) => {
      next?.()
    })

    // Parent app has a fallback after sub-app
    app.use('/sub', subApp)
    app.use('/sub', (_req, res) => {
      res.send('parent fallback')
    })

    const server = app.listen()
    const fetch = makeFetch(server)

    // Request should pass through sub-app and reach parent's next middleware
    await fetch('/sub/test').expect(200, 'parent fallback')
  })
  it('should handle HEAD request reaching fallback handler', async () => {
    const app = new App()

    // Only define GET route, no specific HEAD handler
    app.get('/resource', (_req, res) => {
      res.send('GET response')
    })

    const server = app.listen()
    const fetch = makeFetch(server)

    // HEAD request to existing route
    const response = await fetch('/resource', { method: 'HEAD' })
    expect(response.status).toBe(200)
  })
})

describe('Template engines', () => {
  describe('app.engine', () => {
    it('registers a new engine', () => {
      const app = new App()

      app.engine('.eta', renderFile)

      expect(app.engines).toEqual({ '.eta': renderFile })
    })
    it('appends a dot if not passed', () => {
      const app = new App()

      app.engine('eta', renderFile)

      expect(app.engines).toEqual({ '.eta': renderFile })
    })
  })

  // Ported from https://github.com/expressjs/express/blob/3531987844e533742f1159b0c3f1e07fad2e4597/test/app.render.js
  describe('app.render', async () => {
    it('should support absolute paths', () => {
      const app = new App()

      app.engine('eta', renderFile)
      app.locals.name = 'v1rtl'

      app.render(`${process.cwd()}/tests/fixtures/views/index.eta`, {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
      })
    })
    it('should expose app.locals', () => {
      const app = new App({
        settings: {
          views: `${process.cwd()}/tests/fixtures/views`
        }
      })
      app.engine('eta', renderFile)
      app.locals.name = 'v1rtl'

      app.render('index.eta', {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
      })
    })
    it('should support index files', () => {
      const app = new App({
        settings: {
          views: `${process.cwd()}/tests/fixtures`
        }
      })
      app.engine('eta', renderFile)
      app.set('view engine', 'eta')
      app.locals.name = 'v1rtl'

      app.render('views', {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
      })
    })
    it('should work without a callback', () => {
      const app = new App({
        settings: {
          views: `${process.cwd()}/tests/fixtures/views`
        }
      })
      app.engine('eta', renderFile)
      app.locals.name = 'v1rtl'

      // Should not throw when no callback is provided
      app.render('index.eta', {}, {})
    })
    it('should use view cache in production mode', () => {
      const originalEnv = process.env.NODE_ENV
      process.env.NODE_ENV = 'production'

      const app = new App({
        settings: {
          views: `${process.cwd()}/tests/fixtures/views`
        }
      })
      app.engine('eta', renderFile)
      app.locals.name = 'v1rtl'

      // First render should cache the view
      app.render('index.eta', {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
      })

      // Second render should use cached view
      app.render('index.eta', {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
        expect(app.cache['index.eta']).toBeDefined()
      })

      process.env.NODE_ENV = originalEnv
    })
    it('should handle view engine with leading dot', () => {
      const app = new App({
        settings: {
          views: `${process.cwd()}/tests/fixtures/views`
        }
      })
      // Register engine WITH leading dot
      app.engine('.eta', renderFile)
      // Set view engine WITH leading dot (covers the branch where defaultEngine starts with '.')
      app.set('view engine', '.eta')
      app.locals.name = 'v1rtl'

      app.render('index', {}, {}, (err, str) => {
        if (err) throw err
        expect(str).toEqual('Hello from v1rtl')
      })
    })
    describe('errors', () => {
      it('should catch errors', () => {
        const app = new App({
          settings: {
            views: `${process.cwd()}/tests/fixtures`
          }
        })

        class TestView {
          render() {
            throw new Error('oops')
          }
        }

        app.set('view', TestView as unknown as typeof View)

        app.render('nothing', {}, {}, (err) => {
          expect((err as Error).message, 'err!')
        })
      })
      it('when the file does not exist should provide a helpful error', () => {
        const app = new App({
          settings: {
            views: `${process.cwd()}/tests/fixtures`
          }
        })
        app.engine('eta', renderFile)
        app.render('ate.eta', {}, {}, (err) => {
          expect((err as Error).message).toEqual(
            `Failed to lookup view "ate.eta" in views directory "${process.cwd()}/tests/fixtures"`
          )
        })
      })
      it('when error occurs should trigger a callback', () => {
        const app = new App({
          settings: {
            views: `${process.cwd()}/tests/fixtures/views`
          }
        })
        app.engine('eta', renderFile)
        app.render('error.eta', {}, {}, (err, str) => {
          expect(err).toBeInstanceOf(ReferenceError)
          expect(str).toBeUndefined()
        })
      })
    })

    describe('multiple roots', () => {
      it('should lookup the file in paths', () => {
        const app = new App({
          settings: {
            views: [`${process.cwd()}/tests/fixtures/views/root1`, `${process.cwd()}/tests/fixtures/views/root2`]
          }
        })
        app.engine('eta', renderFile)
        app.locals.user = { name: 'v1rtl' }

        app.render('user.eta', {}, {}, (_, str) => {
          expect(str).toEqual('<p>v1rtl</p>')
        })
      })
      it('should look until the file is found', () => {
        const app = new App({
          settings: {
            views: [`${process.cwd()}/tests/fixtures/views/root1`, `${process.cwd()}/tests/fixtures/views/root2`]
          }
        })
        app.engine('eta', renderFile)

        app.render('home.eta', {}, {}, (_, str) => {
          expect(str).toEqual('this is a home page')
        })
      })
      it('should error if could not find the file', () => {
        const app = new App({
          settings: {
            views: [`${process.cwd()}/tests/fixtures/views/root1`, `${process.cwd()}/tests/fixtures/views/root2`]
          }
        })
        app.engine('eta', renderFile)

        app.render('uknown.eta', {}, {}, (err) => {
          expect((err as Error).message).toMatch(/Failed to lookup view "uknown.eta" in views directories/)
        })
      })
    })

    it('supports custom View', () => {
      const app = new App()

      class TestView {
        name: string
        path = 'test'
        constructor(name: string) {
          this.name = name
        }
        render(_options: never, _data: never, fn: (err: null, msg: string) => void) {
          fn(null, 'testing')
        }
      }

      app.set('view', TestView as unknown as typeof View)

      app.render('something', {}, {}, (_err, str) => {
        expect(str).toEqual('testing')
      })
    })

    describe('caching', () => {
      it('should always lookup view without cache', () => {
        const app = new App()

        let count = 0

        class TestView {
          name: string
          path = 'test'
          constructor(name: string) {
            this.name = name
            count++
          }
          render(_options: never, _data: never, fn: (err: null, msg: string) => void) {
            fn(null, 'testing')
          }
        }

        app.set('view cache', false)
        app.set('view', TestView as unknown as typeof View)

        app.render('something', {}, {}, (_, str) => {
          expect(count).toEqual(1)
          expect(str).toEqual('testing')

          app.render('something', {}, {}, (_, str) => {
            expect(count).toEqual(2)
            expect(str).toEqual('testing')
          })
        })
      })
      it('should cache with "view cache" setting', () => {
        const app = new App()

        let count = 0

        class TestView {
          name: string
          path = 'test'
          constructor(name: string) {
            this.name = name
            count++
          }
          render(_options: never, _data: never, fn: (err: null, msg: string) => void) {
            fn(null, 'testing')
          }
        }

        app.set('view cache', true)
        app.set('view', TestView as unknown as typeof View)

        app.render('something', {}, {}, (_, str) => {
          expect(count).toEqual(1)
          expect(str).toEqual('testing')

          app.render('something', {}, {}, (_, str) => {
            expect(count).toEqual(1)
            expect(str).toEqual('testing')
          })
        })
      })
      it('should respect explicit cache option passed to render()', () => {
        const app = new App()

        let count = 0

        class TestView {
          name: string
          path = 'test'
          constructor(name: string) {
            this.name = name
            count++
          }
          render(_options: never, _data: never, fn: (err: null, msg: string) => void) {
            fn(null, 'cached')
          }
        }

        app.set('view', TestView as unknown as typeof View)

        // Explicitly pass cache: true (this covers the opts.cache != null branch)
        app.render('something', {}, { cache: true }, (_, str) => {
          expect(count).toEqual(1)
          expect(str).toEqual('cached')

          // Second render with explicit cache: true should use cached view
          app.render('something', {}, { cache: true }, (_, str) => {
            expect(count).toEqual(1)
            expect(str).toEqual('cached')
          })
        })
      })
      it('should use default View class when no custom view is set', async () => {
        const app = new App()

        app.engine('eta', renderFile)
        app.set('views', `${process.cwd()}/tests/fixtures/views`)
        app.set('view engine', 'eta')
        app.locals.name = 'default-view-test'

        app.use((_req, res) => {
          res.render('index')
        })

        const server = app.listen()
        const fetch = makeFetch(server)

        await fetch('/').expect(200, 'Hello from default-view-test')
      })
    })
  })
})

