import type { Ranges } from 'header-range-parser'
import { makeFetch } from 'supertest-fetch'
import { describe, expect, it } from 'vitest'
import { App } from '../../packages/app/src'
import {
  checkIfXMLHttpRequest,
  getAccepts,
  getAcceptsCharsets,
  getAcceptsEncodings,
  getAcceptsLanguages,
  getFreshOrStale,
  getRangeFromHeader,
  getRequestHeader,
  reqIs
} from '../../packages/req/src'
import { fresh } from '../../packages/req/src/fresh'
import { runServer } from '../../test_helpers/runServer'

describe('Request extensions', () => {
  describe('req.get(header)', () => {
    it('should return a specified header', async () => {
      const app = runServer((req, res) => {
        res.end(getRequestHeader(req)('accept'))
      })

      await makeFetch(app)('/').expect('*/*')
    })
    it('should handle "referer"', async () => {
      const app = runServer((req, res) => {
        res.end(getRequestHeader(req)('referrer'))
      })

      await makeFetch(app)('/', {
        headers: {
          'Referrer-Policy': 'unsafe-url',
          referer: 'localhost:3000'
        }
      }).expect('localhost:3000')
    })
    it('should handle "referrer"', async () => {
      const app = runServer((req, res) => {
        res.end(getRequestHeader(req)('referrer'))
      })

      await makeFetch(app)('/', {
        headers: {
          'Referrer-Policy': 'unsafe-url',
          referrer: 'localhost:3000'
        }
      }).expect('localhost:3000')
    })
    it('should handle "referer" alternate spelling when called with "referer"', async () => {
      const app = runServer((req, res) => {
        // Use 'referer' spelling when calling getRequestHeader
        res.end(getRequestHeader(req)('referer'))
      })

      await makeFetch(app)('/', {
        headers: {
          'Referrer-Policy': 'unsafe-url',
          referer: 'localhost:3000'
        }
      }).expect('localhost:3000')
    })
  })
  describe('req.xhr', () => {
    it('should be false in node environment', async () => {
      const app = runServer((req, res) => {
        res.end(`Browser request: ${checkIfXMLHttpRequest(req) ? 'yes' : 'no'}`)
      })

      await makeFetch(app)('/').expect('Browser request: no')
    })
    it('should match for any case', async () => {
      const app = new App()
      app.get('/xhr', (req, res) => {
        return res.json({
          xhrHeader: req.headers['x-requested-with'],
          xhr: req.xhr
        })
      })

      await makeFetch(app.listen())('/xhr', { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
        .expectStatus(200)
        .expectBody({
          xhrHeader: 'XMLHttpRequest',
          xhr: true
        })
    })
  })
  describe('req.accepts()', () => {
    it('should detect an "Accept" header', async () => {
      const app = runServer((req, res) => {
        const accepts = getAccepts(req)()

        res.end(accepts[0])
      })

      await makeFetch(app)('/', {
        headers: {
          Accept: 'text/plain'
        }
      }).expect('text/plain')
    })
    it('should parse multiple values', async () => {
      const app = runServer((req, res) => {
        const accepts = getAccepts(req)()

        res.end((accepts as string[]).join(' | '))
      })

      await makeFetch(app)('/', {
        headers: {
          Accept: 'text/plain, text/html'
        }
      }).expect('text/plain | text/html')
    })
  })
  describe('req.acceptsEncodings()', () => {
    it('should detect "Accept-Encoding" header', async () => {
      const app = runServer((req, res) => {
        const encodings = getAcceptsEncodings(req)()

        res.end(encodings[0])
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Encoding': 'gzip'
        }
      }).expect('gzip')
    })
    it('should parse multiple values', async () => {
      const app = runServer((req, res) => {
        const encodings = getAcceptsEncodings(req)()

        res.end((encodings as string[]).join(' | '))
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Encoding': 'gzip, br'
        }
      }).expect('gzip | br | identity')
    })
  })
  describe('req.acceptsCharsets()', () => {
    it('should detect "Accept-Charset" header', async () => {
      const app = runServer((req, res) => {
        const charsets = getAcceptsCharsets(req)()

        res.end(charsets[0])
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Charset': 'utf-8'
        }
      }).expect('utf-8')
    })
    it('should parse multiple values', async () => {
      const app = runServer((req, res) => {
        const charsets = getAcceptsCharsets(req)()

        res.end((charsets as string[]).join(' | '))
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Charset': 'utf-8, iso-8859-1'
        }
      }).expect('utf-8 | iso-8859-1')
    })
  })
  describe('req.acceptsLanguages()', () => {
    it('should detect "Accept-Language" header', async () => {
      const app = runServer((req, res) => {
        const languages = getAcceptsLanguages(req)()

        res.end(languages[0])
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Language': 'ru-RU'
        }
      }).expect('ru-RU')
    })
    it('should parse multiple values', async () => {
      const app = runServer((req, res) => {
        const languages = getAcceptsLanguages(req)()

        res.end((languages as string[]).join(' | '))
      })

      await makeFetch(app)('/', {
        headers: {
          'Accept-Language': 'ru-RU, ru;q=0.9, en-US;q=0.8'
        }
      }).expect('ru-RU | ru | en-US')
    })
  })
  describe('req.fresh', () => {
    it('returns false if method is neither GET nor HEAD', async () => {
      const app = runServer((req, res) => {
        const fresh = getFreshOrStale(req, res)

        res.end(fresh ? 'fresh' : 'stale')
      })

      await makeFetch(app)('/', {
        method: 'POST',
        body: 'Hello World'
      }).expect('stale')
    })
    it('returns true when the resource is not modified', async () => {
      const etag = '123'
      const app = runServer((req, res) => {
        res.setHeader('ETag', etag)
        const fresh = getFreshOrStale(req, res)

        res.end(fresh ? 'fresh' : 'stale')
      })

      await makeFetch(app)('/', {
        headers: {
          'If-None-Match': etag,
          'Cache-Control': 'max-age=3600'
        }
      }).expect('fresh')
    })
    it('should return false when the resource is modified', async () => {
      const etag = '123'
      const app = runServer((req, res) => {
        res.setHeader('ETag', etag)
        const fresh = getFreshOrStale(req, res)

        res.end(fresh ? 'fresh' : 'stale')
      })

      await makeFetch(app)('/', {
        headers: {
          'If-None-Match': '12345'
        }
      }).expect('stale')
    })
    it('returns false if status code is neither >=200 nor < 300, nor 304', async () => {
      const app = runServer((req, res) => {
        res.statusCode = 418

        const fresh = getFreshOrStale(req, res)

        res.end(fresh ? 'fresh' : 'stale')
      })

      await makeFetch(app)('/').expect('stale')
    })
    it('should return false if if-modified-since is greater than last-modified', async () => {
      expect(
        fresh(
          {
            'if-modified-since': new Date(Date.now() - 1000).toUTCString()
          },
          {
            'last-modified': new Date().toUTCString()
          }
        )
      ).toBe(false)
    })
    it('should return false if if-modified-since is defined but last-modified is not', async () => {
      expect(
        fresh(
          {
            'if-modified-since': new Date(Date.now() - 1000).toUTCString()
          },
          {}
        )
      ).toBe(false)
    })
    it('should return true when last-modified is less than or equal to if-modified-since', () => {
      const now = new Date()
      expect(
        fresh(
          {
            'if-modified-since': now.toUTCString()
          },
          {
            'last-modified': new Date(now.getTime() - 1000).toUTCString()
          }
        )
      ).toBe(true)
    })
    it('should match weak ETags (W/ prefix on request)', () => {
      expect(
        fresh(
          {
            'if-none-match': 'W/"123"'
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(true)
    })
    it('should match weak ETags (W/ prefix on response)', () => {
      expect(
        fresh(
          {
            'if-none-match': '"123"'
          },
          {
            etag: 'W/"123"'
          }
        )
      ).toBe(true)
    })
    it('should handle comma-separated ETags in if-none-match', () => {
      expect(
        fresh(
          {
            'if-none-match': '"abc", "123", "xyz"'
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(true)
    })
    it('should return false when ETag does not match any in comma-separated list', () => {
      expect(
        fresh(
          {
            'if-none-match': '"abc", "def", "xyz"'
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(false)
    })
    it('should handle spaces before ETags in if-none-match', () => {
      expect(
        fresh(
          {
            'if-none-match': '   "123"'
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(true)
    })
    it('should handle spaces between comma-separated ETags', () => {
      expect(
        fresh(
          {
            'if-none-match': '"abc",   "123"'
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(true)
    })
    it('should handle spaces within ETag values correctly', () => {
      // Space after characters have been parsed (start !== end)
      expect(
        fresh(
          {
            'if-none-match': '"123" '
          },
          {
            etag: '"123"'
          }
        )
      ).toBe(true)
    })
  })

  describe('req.range', () => {
    it('should return parsed ranges', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        const array = range(300)
        expect(array).toContainEqual({ end: 299, start: 0 })
        expect(array).toHaveLength(1)
        res.end()
      })

      await makeFetch(app)('/', {
        headers: {
          Range: 'bytes=0-1000'
        }
      })
      expect.assertions(2)
    })
    it('should cap to the given size', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        const size = 300
        expect(range(size)?.[0].end).toBe(size - 1)
        res.end()
      })

      await makeFetch(app)('/', {
        headers: {
          Range: 'bytes=0-1000'
        }
      })
      expect.assertions(1)
    })
    it('should cap to the given size when open-ended', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        const size = 300
        expect(range(size)?.[0].end).toBe(size - 1)
        res.end()
      })

      await makeFetch(app)('/', {
        headers: {
          Range: 'bytes=0-'
        }
      })
      expect.assertions(1)
    })
    it('should have a .type', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        expect((range(300) as Ranges).type).toBe('bytes')
        res.end()
      })

      await makeFetch(app)('/', {
        headers: {
          Range: 'bytes=0-1000'
        }
      })
      expect.assertions(1)
    })
    it('should accept any type', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        expect((range(300) as Ranges).type).toBe('any')
        res.end()
      })

      await makeFetch(app)('/', {
        headers: {
          Range: 'any=0-1000'
        }
      })
      expect.assertions(1)
    })
    it('should return undefined if no range', async () => {
      const app = runServer((req, res) => {
        const range = getRangeFromHeader(req)
        expect(range(300)).toBeUndefined()
        res.end()
      })

      await makeFetch(app)('/')
      expect.assertions(1)
    })
    describe('with options', () => {
      it('should return combined ranges if combine set to true', async () => {
        const app = runServer((req, res) => {
          const range = getRangeFromHeader(req)
          const array = range(300, { combine: true })
          expect(array).toContainEqual({ end: 299, start: 0 })
          expect(array).toHaveLength(1)
          res.end()
        })

        await makeFetch(app)('/', {
          headers: {
            Range: 'bytes=0-100, 101-500'
          }
        })
        expect.assertions(2)
      })
      it('should return separated ranges if combine set to false', async () => {
        const app = runServer((req, res) => {
          const range = getRangeFromHeader(req)
          const array = range(300, { combine: false })
          expect(array).toContainEqual({ end: 100, start: 0 })
          expect(array).toContainEqual({ end: 299, start: 101 })
          expect(array).toHaveLength(2)
          res.end()
        })

        await makeFetch(app)('/', {
          headers: {
            Range: 'bytes=0-100, 101-500'
          }
        })
        expect.assertions(3)
      })
    })
  })
  describe('req.is', () => {
    it('should return the given MIME type when matching', async () => {
      const app = runServer((req, res) => {
        expect(reqIs(req)('text/plain')).toBe('text/plain')
        res.end()
      })
      await makeFetch(app)('/', {
        headers: {
          'Content-Type': 'text/plain'
        }
      })
      expect.assertions(1)
    })
    it('should return false when not matching', async () => {
      const app = runServer((req, res) => {
        expect(reqIs(req)('text/other')).toBe(false)
        res.end()
      })
      await makeFetch(app)('/', {
        headers: {
          'Content-Type': 'text/plain'
        }
      })
      expect.assertions(1)
    })
    it('should return false when Content-Type header is not present', async () => {
      const app = runServer((req, res) => {
        expect(reqIs(req)('text/other')).toBe(false)
        res.end()
      })
      await makeFetch(app)('/', {
        headers: {}
      })
      expect.assertions(1)
    })
    it("Should lookup the MIME type with the extension given (e.g. req.is('json')", async () => {
      const app = runServer((req, res) => {
        expect(reqIs(req)('json')).toBe('json')
        res.end()
      })
      await makeFetch(app)('/', {
        headers: {
          'Content-Type': 'application/json'
        }
      })
      expect.assertions(1)
    })
    it('should ignore charset', async () => {
      const app = runServer((req, res) => {
        expect(reqIs(req)('text/html')).toBe('text/html')
        res.end()
      })
      await makeFetch(app)('/', {
        headers: {
          'Content-Type': 'text/html; charset=UTF-8'
        }
      })

      expect.assertions(1)
    })
  })
})

