import type { Stats } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { eTag } from '../../packages/etag/src'

describe('etag(entity)', () => {
  it('should require an entity', () => {
    try {
      eTag(undefined as unknown as string)
    } catch (e) {
      expect((e as TypeError).message).toBe('argument entity is required')
    }
  })
  it('should generate a strong ETag', () => {
    expect(eTag('beep boop')).toBe('"9-fINXV39R1PCo05OqGqr7KIY9lCE"')
  })
  it('should work for empty string', () => {
    expect(eTag('')).toBe('"0-2jmj7l5rSw0yVb/vlWAYkK/YBwk"')
  })
  it('should work containing Unicode', () => {
    expect(eTag('论')).toBe('"3-QkSKq8sXBjHL2tFAZknA2n6LYzM"')
    expect(eTag('论', { weak: true })).toBe('W/"3-QkSKq8sXBjHL2tFAZknA2n6LYzM"')
  })
  it('should reject number entities', () => {
    expect(() => eTag(<any>1)).toThrow('Received type number')
  })
  describe('Buffer', () => {
    it('should work on empty', () => {
      expect(eTag(Buffer.from(''))).toBe('"0-2jmj7l5rSw0yVb/vlWAYkK/YBwk"')
    })
    it('should generate a strong ETag', () => {
      expect(eTag(Buffer.from('beep boop'))).toBe('"9-fINXV39R1PCo05OqGqr7KIY9lCE"')
    })
  })
  describe('fs.Stats', () => {
    it('should generate a weak ETag', () => {
      const stats = {
        mtime: new Date(Date.UTC(2020, 1, 1)),
        size: 1024
      } as Stats
      expect(eTag(stats)).toBe('W/"16ffe0c0c00-400"')
    })
  })
  describe('weak', () => {
    it('should generate a weak ETag', () => {
      expect(eTag('beep boop', { weak: true })).toBe('W/"9-fINXV39R1PCo05OqGqr7KIY9lCE"')
    })
    it('should generate a strong ETag', () => {
      expect(eTag('beep boop', { weak: false })).toBe('"9-fINXV39R1PCo05OqGqr7KIY9lCE"')
    })
  })
})

tests/wares/rate-limit/memory-store.test.source:
import { describe, expect, it, vi } from 'vitest'
import { MemoryStore } from '../../../packages/rate-limit/src'

const key = '127.0.0.1'

const testHelper = (increaseFunction, key: string): Promise<{ current: number }> => {
  return new Promise((resolve) => {
    increaseFunction(key, (_, hitCount) => resolve({ current: hitCount }))
  })
}

describe('MemoryStore store', () => {
  it('sets the value to 1 on first incr', async () => {
    const store = new MemoryStore(-1)

    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
  })

  it('increments the key for the store each increment', async () => {
    const store = new MemoryStore(-1)

    await testHelper(store.incr, key)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 2)
  })

  it('resets the key for the store when used with resetKey', async () => {
    const store = new MemoryStore(-1)

    await testHelper(store.incr, key)
    await testHelper(store.incr, key)
    store.resetKey(key)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
  })

  it('resets the key for the store when used with resetAll', async () => {
    const store = new MemoryStore(-1)

    await testHelper(store.incr, key)
    await testHelper(store.incr, key)
    store.resetAll()
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
  })

  it('resets all keys for the store when the timeout is reached', async () => {
    vi.useFakeTimers()
    const store = new MemoryStore(50)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
    vi.advanceTimersByTime(100)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
  })

  it('decrements the key for the store each decrement', async () => {
    const store = new MemoryStore(-1)

    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 2)
    await store.decrement(key)
    await store.decrement(key)
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
  })

  it('decrements the key for the store each decrement', async () => {
    const store = new MemoryStore(-1)

    assertCurrentAfterIncrement(await testHelper(store.incr, key), 1)
    await store.decrement('randomKey')
    assertCurrentAfterIncrement(await testHelper(store.incr, key), 2)
  })
})

function assertCurrentAfterIncrement(result: { current: number }, expectedValue: number) {
  expect(result.current).toEqual(expectedValue)
}

